const REGIONS={AFRO:'African Region',AMRO:'Region of the Americas',EMRO:'Eastern Mediterranean',EURO:'European Region',SEARO:'South-East Asia',WPRO:'Western Pacific'};
const DEV=['Least developed','Developing','Economy in transition','Developed economy'];
const COLORS=['#edf5ed','#c5e0cb','#87bfa6','#409781','#166352'];
const state={data:[],world:null,view:'map',timer:null,selectedYears:null};
const fields=['country','iso3','year','population','cases','incidence','mcv1','mcv2','region','income_group','development_status','gavi_eligible'];
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(state.toast);state.toast=setTimeout(()=>$('#toast').hidden=true,7000)}
function aggregate(rows){const mean=k=>{const rr=rows.filter(r=>available(r[k]));if(!rr.length)return null;return rr.every(r=>r.population>0)?d3.sum(rr,r=>r[k]*r.population)/d3.sum(rr,r=>r.population):d3.mean(rr,r=>r[k])};const valid=rows.filter(r=>r.population>0);const incidence=valid.length&&valid.length===rows.length&&valid.every(r=>available(r.cases)||available(r.incidence))?d3.sum(valid,r=>available(r.cases)?r.cases:r.incidence*r.population/1e6)/d3.sum(valid,r=>r.population)*1e6:mean('incidence');const caseRows=rows.filter(r=>available(r.cases));return {mcv1:mean('mcv1'),mcv2:mean('mcv2'),incidence,cases:caseRows.length?d3.sum(caseRows,r=>r.cases):null,weighted:k=>{const rr=rows.filter(r=>available(r[k]));return rr.length&&rr.every(r=>r.population>0)}}}
function filtered(allYears=false){const dev=[...document.querySelectorAll('[name="development"]:checked')].map(n=>n.value);return state.data.filter(r=>(allYears||r.year===+$('#year').value)&&(!$('#income').value||r.income_group===$('#income').value)&&(!$('#gavi').checked||r.gavi_eligible)&&(!dev.length||dev.includes(r.development_status)))}
function setView(v){stop();state.view=v;document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('active',b.dataset.view===v));['map','trends','regions'].forEach(k=>$('#'+k+'View').hidden=k!==v);$('#metricWrap').hidden=v!=='map';$('#countryWrap').hidden=v!=='trends';render()}
function render(){const base=filtered(),rows=state.view==='trends'?base.filter(r=>r.iso3===$('#country').value):state.view==='regions'&&$('#region').value?base.filter(r=>r.region===$('#region').value):base,a=aggregate(rows),year=$('#year').value;$('#yearLabel').textContent=year;$('#recordCount').textContent=`${new Set(state.data.map(r=>r.iso3)).size} countries · ${d3.min(state.data,r=>r.year)}–${d3.max(state.data,r=>r.year)}`;const stats=[['Reported measles cases',fmt(a.cases),'',`${rows.filter(r=>available(r.cases)).length} reporting countries`],['Measles incidence',fmt(a.incidence,1),' / million',a.weighted('incidence')?'Population weighted':'Country mean · available values'],['First-dose coverage',fmt(a.mcv1,1),'%',a.weighted('mcv1')?'Population weighted · MCV1':'Country mean · MCV1'],['Second-dose coverage',fmt(a.mcv2,1),'%',a.weighted('mcv2')?'Population weighted · MCV2':'Country mean · MCV2']];$('#stats').replaceChildren(...stats.map(([label,val,unit,note])=>{const e=document.createElement('div');e.className='stat';const l=document.createElement('div');l.className='stat-label';l.textContent=label;const v=document.createElement('div');v.className='stat-value';v.textContent=val;const u=document.createElement('small');u.textContent=val==='No data'?'':unit;v.append(u);const n=document.createElement('div');n.className='stat-note';n.textContent=note;e.append(l,v,n);return e}));if(state.view==='map')renderMap(rows);if(state.view==='trends')renderTrends();if(state.view==='regions')renderRegions()}
let mapGroup,mapPath,mapZoom;
function initMap(){const projection=d3.geoNaturalEarth1().fitExtent([[12,15],[988,450]],state.world);mapPath=d3.geoPath(projection);const svg=d3.select('#map');mapGroup=svg.append('g');mapGroup.append('path').datum({type:'Sphere'}).attr('d',mapPath).attr('fill','#f6f9f8');mapGroup.selectAll('.country').data(state.world.features.filter(f=>f.properties['ISO3166-1-Alpha-3']!=='ATA')).join('path').attr('class','country').attr('d',mapPath).attr('tabindex',0).on('pointermove',showCountry).on('pointerleave',()=>$('#tooltip').hidden=true).on('focus',function(e,f){showCountry(e,f)}).on('blur',()=>$('#tooltip').hidden=true).on('click',selectCountry).on('keydown',(e,f)=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectCountry(e,f)}});mapZoom=d3.zoom().scaleExtent([1,7]).on('zoom',e=>mapGroup.attr('transform',e.transform));svg.call(mapZoom);$('#zoomIn').onclick=()=>svg.transition().call(mapZoom.scaleBy,1.4);$('#zoomOut').onclick=()=>svg.transition().call(mapZoom.scaleBy,1/1.4);$('#zoomReset').onclick=()=>svg.transition().call(mapZoom.transform,d3.zoomIdentity)}
function mapRow(f){return filtered().find(r=>r.iso3===f.properties['ISO3166-1-Alpha-3'])}
function selectCountry(e,f){const r=mapRow(f);if(!r){toast('No matching data for this country and current filters.');return}$('#country').value=r.iso3;state.selectedYears=null;$('#tooltip').hidden=true;setView('trends')}
function showCountry(e,f){const r=mapRow(f),name=r?.country||f.properties.name;const tip=$('#tooltip');tip.replaceChildren();const strong=document.createElement('strong');strong.textContent=name;tip.append(strong,document.createElement('br'));tip.append(document.createTextNode(r?`${$('#year').value} · Incidence: ${fmt(r.incidence,1)} / million`:'No data for current filters'),document.createElement('br'));if(r)tip.append(document.createTextNode(`MCV1: ${fmt(r.mcv1,1)}% · MCV2: ${fmt(r.mcv2,1)}%`));tip.hidden=false;const box=e.target.getBoundingClientRect();tip.style.left=Math.min(e.clientX||box.x,window.innerWidth-270)+'px';tip.style.top=Math.min((e.clientY||box.y)+18,window.innerHeight-130)+'px';$('#countryTitle').textContent=name;$('#countryInfo').textContent=r?`${fmt(r.cases)} reported cases in ${r.year}. ${r.region||'Region not provided'}. Select to explore trends.`:'No observation available for the selected year and filters.'}
function renderMap(rows){const metric=$('#metric').value,coverage=metric.startsWith('mcv'),thresholds=coverage?[50,80,90,95]:metric==='cases'?[1,100,1000,10000]:[1,10,100,1000],scale=d3.scaleThreshold(thresholds,COLORS),lookup=new Map(rows.map(r=>[r.iso3,r]));mapGroup.selectAll('.country').attr('fill',f=>{const r=lookup.get(f.properties['ISO3166-1-Alpha-3']);return r&&available(r[metric])?scale(r[metric]):'#e6eae7'}).attr('aria-label',f=>{const r=lookup.get(f.properties['ISO3166-1-Alpha-3']);return `${f.properties.name}: ${r?fmt(r[metric],1):'No data'}`});$('#mapTitle').textContent=$('#metric').selectedOptions[0].textContent;$('#mapSubtitle').textContent=`${coverage?'Vaccination coverage (%)':metric==='cases'?'Reported cases':'Reported cases per million population'} · ${$('#year').value}`;const labels=coverage?['<50%','50–79%','80–89%','90–94%','≥95%']:metric==='cases'?['0','1–99','100–999','1k–9.9k','≥10k']:['<1','1–9.9','10–99','100–999','≥1,000'];$('#legend').replaceChildren(...[...labels,'No data'].map((l,i)=>{const s=document.createElement('span');s.className='legend-item';const c=document.createElement('i');c.className='swatch';c.style.background=COLORS[i]||'#e6eae7';s.append(c,document.createTextNode(l));return s}))}
function yearly(rows){return [...d3.group(rows,r=>r.year)].map(([year,rr])=>({year,...aggregate(rr)})).sort((a,b)=>a.year-b.year)}
function completeYears(rows,start,end){const m=new Map(rows.map(r=>[r.year,r]));return d3.range(start,end+1).map(year=>m.get(year)||{year})}
function lineChart(target,rows,keys,options={}){const width=options.width||1100,height=options.height||225,m={top:35,right:50,bottom:32,left:58};const svg=d3.select(target).append('svg').attr('class','chart-svg').attr('viewBox',`0 0 ${width} ${height}`).attr('role','img').attr('aria-label',options.title||'Time series');const domain=options.domain||d3.extent(rows,r=>r.year);const x=d3.scaleLinear().domain(domain[0]===domain[1]?[domain[0]-.5,domain[1]+.5]:domain).range([m.left,width-m.right]);const max=d3.max(rows,r=>r.incidence)||1;const y=d3.scaleLinear().domain([0,options.coverage?100:d3.max(rows,r=>d3.max(keys,k=>r[k]))||1]).nice().range([height-m.bottom,m.top]);const y2=d3.scaleLinear().domain([0,max]).nice().range([height-m.bottom,m.top]);svg.append('g').attr('class','axis').attr('transform',`translate(0,${height-m.bottom})`).call(d3.axisBottom(x).ticks(options.mini?3:8).tickFormat(d3.format('d')).tickSize(0).tickPadding(12));svg.append('g').attr('class','axis').attr('transform',`translate(${m.left},0)`).call(d3.axisLeft(y).ticks(options.mini?3:4).tickSize(-(width-m.left-m.right)).tickPadding(8));if(options.dual)svg.append('g').attr('class','axis').attr('transform',`translate(${width-m.right},0)`).call(d3.axisRight(y2).ticks(3).tickSize(0));svg.append('text').attr('class','chart-title').attr('x',m.left).attr('y',17).text(options.title||'');const colors={mcv1:'#147d70',mcv2:'#76a8c0',incidence:'#d58b51'};keys.forEach(k=>{const yy=options.dual&&k==='incidence'?y2:y;svg.append('path').datum(rows).attr('fill','none').attr('stroke',colors[k]).attr('stroke-width',options.mini?2:2.7).attr('d',d3.line().defined(r=>available(r[k])).x(r=>x(r.year)).y(r=>yy(r[k])));svg.selectAll('.point-'+k).data(rows.filter(r=>available(r[k]))).join('circle').attr('cx',r=>x(r.year)).attr('cy',r=>yy(r[k])).attr('r',options.mini?1:2.5).attr('fill',colors[k]).append('title').text(r=>`${r.year} · ${k.toUpperCase()}: ${fmt(r[k],1)}`)});if(!rows.some(r=>keys.some(k=>available(r[k]))))svg.append('text').attr('x',width/2).attr('y',height/2).attr('text-anchor','middle').attr('fill','#82968c').text('No data for these filters');return {svg,x}}
function renderTrends(skipBrush=false){const iso=$('#country').value,rr=filtered(true).filter(r=>r.iso3===iso),name=state.data.find(r=>r.iso3===iso)?.country||'Country';$('#trendTitle').textContent=`${name} · trends over time`;const extent=[+$('#year').min,+$('#year').max],domain=state.selectedYears||extent,rows=completeYears(rr,...extent).filter(r=>r.year>=domain[0]&&r.year<=domain[1]);$('#trendCharts').replaceChildren();lineChart('#trendCharts',rows,['mcv1','mcv2'],{coverage:true,title:'Vaccination coverage (%)',domain});lineChart('#trendCharts',rows,['incidence'],{title:'Measles incidence · per million population',domain,height:210});if(!skipBrush){const svg=d3.select('#brush');svg.selectAll('*').remove();const x=d3.scaleLinear().domain(extent[0]===extent[1]?[extent[0]-.5,extent[1]+.5]:extent).range([58,1050]),y=d3.scaleLinear().domain([0,d3.max(rr,r=>r.incidence)||1]).range([60,15]);svg.append('path').datum(completeYears(rr,...extent)).attr('fill','none').attr('stroke','#a4c7b6').attr('stroke-width',2).attr('d',d3.line().defined(r=>available(r.incidence)).x(r=>x(r.year)).y(r=>y(r.incidence)));svg.append('rect').attr('x',58).attr('y',8).attr('width',992).attr('height',57).attr('rx',4).attr('fill','#147d70').attr('fill-opacity',.035).attr('stroke','#d9e7de');const brush=d3.brushX().extent([[58,8],[1050,65]]).on('end',event=>{if(!event.sourceEvent)return;state.selectedYears=event.selection?event.selection.map(v=>Math.round(x.invert(v))):null;renderTrends(true)});const g=svg.append('g').call(brush);if(state.selectedYears)g.call(brush.move,state.selectedYears.map(x));svg.selectAll('.selection').attr('fill','#147d70').attr('fill-opacity',.12).attr('stroke','#147d70')}}
function renderRegions(){const all=filtered(true),start=+$('#startYear').value,end=+$('#endYear').value;const groups=['GLOBAL',...Object.keys(REGIONS)].filter(k=>!$('#region').value||k===$('#region').value);$('#smallMultiples').replaceChildren();groups.forEach(k=>{const rr=all.filter(r=>(k==='GLOBAL'||r.region===k)&&r.year>=start&&r.year<=end),a=yearly(rr);const box=document.createElement('div');box.className='mini';const h=document.createElement('h3');h.textContent=k==='GLOBAL'?'Global':k;const p=document.createElement('p');p.textContent=k==='GLOBAL'?'All countries in the current selection':REGIONS[k];box.append(h,p);$('#smallMultiples').append(box);lineChart(box,completeYears(a,start,end),['mcv1','incidence'],{width:390,height:205,mini:true,coverage:true,dual:true,domain:[start,end]})});const regions=Object.keys(REGIONS).filter(k=>!$('#region').value||k===$('#region').value).map(region=>({region,...aggregate(all.filter(r=>r.region===region&&r.year===+$('#year').value))}));bars('#vaccineBars',regions,['mcv1','mcv2'],100);const unit=+$('#incidenceUnit').value;bars('#incidenceBars',regions.map(r=>({...r,incidence:available(r.incidence)?r.incidence*unit/1e6:null})),['incidence']);}
function bars(target,rows,keys,max){$(target).replaceChildren();const svg=d3.select(target).append('svg').attr('class','chart-svg').attr('viewBox','0 0 560 270').attr('role','img').attr('aria-label','Regional bar comparison'),x=d3.scaleBand().domain(rows.map(r=>r.region)).range([55,535]).padding(.35),y=d3.scaleLinear().domain([0,max||d3.max(rows,r=>r.incidence)||1]).nice().range([225,30]);svg.append('g').attr('class','axis').attr('transform','translate(55,0)').call(d3.axisLeft(y).ticks(4).tickSize(-480));svg.append('g').attr('class','axis').attr('transform','translate(0,225)').call(d3.axisBottom(x).tickSize(0).tickPadding(15));rows.forEach(r=>keys.forEach((k,i)=>{if(!available(r[k])){svg.append('text').attr('x',x(r.region)+x.bandwidth()/2).attr('y',215-i*14).attr('text-anchor','middle').attr('font-size',8).attr('fill','#84988c').text('No data');return}const bw=x.bandwidth()/keys.length;svg.append('rect').attr('x',x(r.region)+i*bw).attr('width',bw-3).attr('y',y(r[k])).attr('height',225-y(r[k])).attr('rx',3).attr('fill',k==='incidence'?'#d58b51':i?'#a7cdbd':'#147d70').append('title').text(`${r.region} · ${k}: ${fmt(r[k],2)}`)}))}
function stop(){clearInterval(state.timer);state.timer=null;$('#play').textContent='▶';$('#play').setAttribute('aria-label','Play years')}
function loadData(data,label){stop();state.data=data;state.selectedYears=null;const years=[...new Set(data.map(r=>r.year))].sort((a,b)=>a-b);$('#year').min=years[0];$('#year').max=years.at(-1);$('#year').value=years.at(-1);$('#yearEnd').textContent=years.at(-1);const opts=years.map(y=>new Option(y,y));$('#startYear').replaceChildren(...opts);$('#endYear').replaceChildren(...years.map(y=>new Option(y,y)));$('#endYear').value=years.at(-1);const countries=[...new Map(data.map(r=>[r.iso3,r.country])).entries()].sort((a,b)=>a[1].localeCompare(b[1]));$('#country').replaceChildren(...countries.map(([iso,name])=>new Option(name,iso)));$('#country').value=countries.some(([iso])=>iso==='IND')?'IND':countries[0][0];$('#datasetName').textContent=label||'Illustrative dataset';$('#datasetDetail').textContent=label?`${data.length.toLocaleString()} rows loaded · processed locally in your browser`:'Synthetic data for exploring the dashboard. Not surveillance estimates.';clearFilters(false);render()}
function clearFilters(draw=true){$('#income').value='';$('#gavi').checked=false;document.querySelectorAll('[name="development"]').forEach(n=>n.checked=false);$('#region').value='';if(draw)render()}
function parseCSV(text){const parsed=d3.csvParse(text.replace(/^\uFEFF/,''));const cols=parsed.columns;if(!['country','iso3','year'].every(k=>cols.includes(k)))throw Error('Required columns: country, iso3, year. Download the template for the full schema.');if(!['incidence','cases','mcv1','mcv2'].some(k=>cols.includes(k)))throw Error('Include at least one measure: incidence, cases, mcv1, or mcv2.');const seen=new Set();const rows=parsed.map((r,i)=>{const row={...r,country:r.country.trim(),iso3:r.iso3.trim().toUpperCase()};if(!row.country||!(/^[A-Z]{3}$/.test(row.iso3)))throw Error(`Row ${i+2}: country and a three-letter ISO3 code are required.`);for(const k of ['year','population','cases','incidence','mcv1','mcv2']){const v=(r[k]||'').trim();row[k]=v===''?null:Number(v);if(v!==''&&!Number.isFinite(row[k]))throw Error(`Row ${i+2}: ${k} must be numeric or blank.`)}if(!Number.isInteger(row.year)||row.year<1900||row.year>2100)throw Error(`Row ${i+2}: year must be a whole number from 1900 to 2100.`);for(const k of ['population','cases','incidence','mcv1','mcv2'])if(row[k]!=null&&(row[k]<0||(k.startsWith('mcv')&&row[k]>100)||(k==='population'&&row[k]===0)))throw Error(`Row ${i+2}: invalid ${k}; coverage must be 0–100 and population positive.`);const key=row.iso3+row.year;if(seen.has(key))throw Error(`Row ${i+2}: duplicate country/year ${key}.`);seen.add(key);const flag=(r.gavi_eligible||'').trim().toLowerCase();if(!['','true','false','1','0','yes','no'].includes(flag))throw Error(`Row ${i+2}: gavi_eligible must be true or false.`);row.gavi_eligible=['true','1','yes'].includes(flag);for(const k of ['region','income_group','development_status'])row[k]=(r[k]||'').trim();if(row.region&&!Object.hasOwn(REGIONS,row.region))throw Error(`Row ${i+2}: use a WHO region code from the template.`);if(row.incidence===null&&row.cases!==null&&row.population)row.incidence=row.cases/row.population*1e6;return row});if(!rows.length)throw Error('The dataset contains no data rows.');if(!rows.some(r=>['incidence','cases','mcv1','mcv2'].some(k=>available(r[k]))))throw Error('No numeric observations found.');return rows}
$('#upload').onclick=()=>$('#file').click();$('#file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>20*1024*1024)throw Error('Please use a CSV smaller than 20 MB.');const rows=parseCSV(await file.text());loadData(rows,file.name);const mapped=new Set(state.world.features.map(f=>f.properties['ISO3166-1-Alpha-3']));const missing=[...new Set(rows.filter(r=>!mapped.has(r.iso3)).map(r=>r.iso3))];toast(missing.length?`Loaded. Codes without map boundaries: ${missing.join(', ')}. Their data remains in charts.`:`Loaded ${rows.length.toLocaleString()} observations.`)}catch(error){toast(error.message)}e.target.value=''};
$('#download').onclick=async()=>{const text=await(await fetch('template.csv')).text();const url=URL.createObjectURL(new Blob([text],{type:'text/csv'})),a=document.createElement('a');a.href=url;a.download='measles-template.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),500)};$('#resetData').onclick=()=>loadData(state.demo);document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>setView(b.dataset.view));['metric','income','gavi','country','region','incidenceUnit'].forEach(k=>$('#'+k).onchange=()=>{state.selectedYears=null;render()});$('#year').oninput=render;$('#clearFilters').onclick=()=>clearFilters();$('#play').onclick=()=>{if(state.timer){stop();return}$('#play').textContent='Ⅱ';$('#play').setAttribute('aria-label','Pause years');if(+$('#year').value===+$('#year').max)$('#year').value=$('#year').min;render();state.timer=setInterval(()=>{if(+$('#year').value>=+$('#year').max){stop();return}$('#year').value=+$('#year').value+1;render()},700)};['startYear','endYear'].forEach(k=>$('#'+k).onchange=()=>{if(+$('#startYear').value>+$('#endYear').value)$('#'+(k==='startYear'?'endYear':'startYear')).value=$('#'+k).value;render()});$('#methodology').onclick=()=>$('#dataDialog').showModal();$('#closeDialog').onclick=()=>$('#dataDialog').close();
(async()=>{try{const [world,demo]=await Promise.all([fetch('assets/world.geojson').then(r=>{if(!r.ok)throw Error('Map could not load');return r.json()}),fetch('demo.csv').then(r=>r.text())]);state.world=world;state.demo=parseCSV(demo);DEV.forEach(d=>{const l=document.createElement('label');l.className='check';const i=document.createElement('input');i.type='checkbox';i.name='development';i.value=d;i.onchange=render;l.append(i,document.createTextNode(d));$('#developmentFilters').append(l)});Object.entries(REGIONS).forEach(([k,v])=>$('#region').add(new Option(`${k} · ${v}`,k)));initMap();loadData(state.demo)}catch(e){toast(`Unable to start: ${e.message}. Run the app with the Python server.`)}})();
